def truncated_judge_masses(cells, gamma, b=4.0):
    """Truncated GA-style singleton masses: each judge's within-week softmax masses
    over couples, scaled down so that the total singleton mass never exceeds
    cap(k)/b (cap = 1,2,4,7 for k = 1..4 focal sets).  Shafer (1976) leaves the
    singleton masses underdetermined; the capping here mirrors the truncated
    Dempster rule and prevents near-duplicate judge opinions from conspiring into
    cosmological conflicts when |Theta| is large."""
    n, nj = cells.shape
    p = np.zeros((n, nj))
    for j in range(nj):
        logits = gamma * cells[:, j]
        p[:, j] = softmax(logits - logits.max())
    # cap total singleton mass at cap(k)/b, k = max #focal sets sharing common mass
    srt = np.sort(p, axis=0)[::-1]
    def cap_cap(k):
        return 1.0 + 0.5 * k * (k - 1)
    # find the largest k whose cumulative order-statistic bound is satisfiable
    k_ok = 1
    for kk in range(1, n + 1):
        if srt[:kk].sum(axis=0).min() <= cap_cap(kk) / b:
            k_ok = kk
        else:
            break
    allowed = min(cap_cap(k_ok) / b, 1.0)
    out = p.copy()
    tot = out.sum(axis=0, keepdims=True)
    if tot.max() > allowed:
        over = (tot > allowed).ravel()
        for j in np.where(over)[0]:
            s = out[:, j]
            floor = 0.5 * np.sort(s)[::-1][k_ok - 1]
            excess = s.sum() - allowed
            for _ in range(80):
                if excess <= 1e-12:
                    break
                room_mask = s > floor
                room = (s[room_mask] - floor).sum()
                if room <= 0:
                    floor *= 0.7
                    continue
                take = min(excess, room)
                s[room_mask] = s[room_mask] - (s[room_mask] - floor) * (take / room)
                excess = s.sum() - allowed
                if excess > 1e-9:
                    floor *= 0.8
    return out / out.sum(axis=0, keepdims=True)

